  /* ═══════════════════════════════════════════
     2026-09-10 RESTRUCTURE — hero includes, patient-story videos, booking band.
     Added when the price card and the lead form moved out of the hero.
     ═══════════════════════════════════════════ */
  .well-lp__hero-includes {
    list-style: none;
    margin: 0 0 24px;
    padding: 0;
    display: grid;
    gap: 10px;
    max-width: 520px;
  }
  .well-lp__hero-includes li {
    position: relative;
    padding-left: 30px;
    font-size: 16px;
    line-height: 1.45;
    color: var(--cloud);
  }
  .well-lp__hero-includes li::before {
    content: '';
    position: absolute;
    left: 0; top: 5px;
    width: 18px; height: 18px;
    border-radius: 50%;
    background: rgba(13,148,136,0.22);
    border: 1px solid rgba(94,234,212,0.45);
    background-image: url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%235eead4' stroke-width='3.5' stroke-linecap='round' stroke-linejoin='round'%3E%3Cpolyline points='20 6 9 17 4 12'/%3E%3C/svg%3E");
    background-size: 12px 12px;
    background-repeat: no-repeat;
    background-position: center;
  }
  .well-lp__hero-includes li.is-emphasis {
    color: var(--white);
    font-weight: 600;
  }

  /* Video facade: thumbnail until clicked, then the real iframe. */
  .well-lp__video-card { width: 100%; }
  .well-lp__video-thumb {
    display: block;
    position: relative;
    width: 100%;
    aspect-ratio: 16 / 9;
    padding: 0;
    border: 1px solid rgba(255,255,255,0.10);
    border-radius: var(--radius);
    overflow: hidden;
    cursor: pointer;
    background: #000;
    transition: border-color 200ms ease, transform 200ms ease;
  }
  .well-lp__video-thumb:hover { border-color: rgba(58,146,218,0.55); transform: translateY(-2px); }
  .well-lp__video-thumb img {
    width: 100%; height: 100%;
    object-fit: cover;
    display: block;
    /* hqdefault is 480x360 — 16:9 content with a 45px letterbox bar top and
       bottom. Covering a 16:9 box crops exactly those two bars, so no extra
       scaling: hqdefault is used rather than maxresdefault because maxres is
       missing on some of these uploads (cpha9Dp08g0 404s). */
  }
  .well-lp__video-play {
    position: absolute;
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
    width: 64px; height: 64px;
    border-radius: 50%;
    background: rgba(58,146,218,0.92);
    box-shadow: 0 6px 24px rgba(0,0,0,0.45);
    transition: background 200ms ease;
  }
  .well-lp__video-play::after {
    content: '';
    position: absolute;
    top: 50%; left: 54%;
    transform: translate(-50%, -50%);
    border-style: solid;
    border-width: 11px 0 11px 18px;
    border-color: transparent transparent transparent #fff;
  }
  .well-lp__video-thumb:hover .well-lp__video-play { background: var(--accent); }
  .well-lp__video-card iframe {
    width: 100%;
    aspect-ratio: 16 / 9;
    border: 0;
    border-radius: var(--radius);
    display: block;
  }
  .well-lp__video-title {
    font-family: var(--font-heading);
    font-size: 15px;
    font-weight: 600;
    color: var(--white);
    margin-top: 12px;
    letter-spacing: -0.2px;
  }

  .well-lp__hero-video { position: relative; z-index: 1; }
  .well-lp__hero-video-cap {
    font-size: 14px;
    color: var(--mist);
    margin-top: 12px;
    text-align: center;
  }

  /* ⚠️ This band is the only DARK one that uses the shared section-head classes.
     Those default to --ink text because every other section that uses them sits on
     a light background, so without these three overrides the heading, eyebrow and
     subhead render --ink on --ink — invisible, and invisible in a way no build
     check catches. */
  .well-lp__videos { padding: clamp(56px, 7vw, 88px) 0; background: var(--ink); }
  .well-lp__videos .well-lp__h2 { color: var(--white); }
  .well-lp__videos .well-lp__eyebrow { color: var(--accent-glow); }
  .well-lp__videos .well-lp__sub { color: var(--cloud); }
  .well-lp__video-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 28px;
  }
  .well-lp__video-more { text-align: center; margin-top: 32px; }
  .well-lp__video-more a {
    font-family: var(--font-heading);
    font-weight: 600;
    font-size: 15px;
    color: var(--accent-glow);
    text-decoration: none;
  }
  .well-lp__video-more a:hover { text-decoration: underline; }

  /* Booking band: the price device and the form, together, low on the page.
     ⚠️ DARK on purpose. The offer card (.well-lp__offer-card and everything in it)
     was authored for the dark hero — white text on a translucent blue gradient — so
     dropping it onto a light band renders the heading and the "You save $303" pill
     nearly invisible. Restyling the card for light would fork one device into two
     skins; giving the band the background the card already expects does not. The
     white form card reads on dark exactly as it did in the hero. */
  .well-lp__book { padding: clamp(56px, 7vw, 88px) 0; background: var(--ink); }
  .well-lp__book .well-lp__h2 { color: var(--white); }
  .well-lp__book .well-lp__eyebrow { color: var(--accent-glow); }
  .well-lp__book .well-lp__sub { color: var(--cloud); }
  .well-lp__book-grid {
    display: grid;
    grid-template-columns: 1fr 440px;
    gap: 48px;
    align-items: start;
  }
  .well-lp__book .well-lp__offer-card { margin-bottom: 0; }
  .well-lp__book .well-lp__form-card { margin-top: 0; }

  @media (max-width: 980px) {
    .well-lp__video-grid { grid-template-columns: 1fr; gap: 24px; }
    .well-lp__book-grid { grid-template-columns: 1fr; gap: 32px; }
  }
</style>

document.getElementById('wlp-year').textContent=new Date().getFullYear();
document.querySelectorAll('.well-lp__video-card').forEach(function(card){
var btn=card.querySelector('.well-lp__video-thumb');if(!btn)return;
btn.addEventListener('click',function(){
var id=card.getAttribute('data-yt');
var f=document.createElement('iframe');
f.src='https://www.youtube-nocookie.com/embed/'+id+'?autoplay=1&rel=0&modestbranding=1';
f.title=btn.getAttribute('aria-label')||'Patient story';
f.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture';
f.setAttribute('allowfullscreen','');
btn.replaceWith(f);
if(window.dataLayer){window.dataLayer.push({event:'video_play',video_id:id})}
})});
